/*PUSU_NS*//* PUSU harita nesneleri — sunucu (isci.js). Harita tanımındaki kur.nesneler (cam / kapi) her raund başında
   duvar olarak kurulur (no = -(sıra+1)); kurşun hasar verir, kırılınca "duvaryok" yayılır. Ara katılana kırıklar gönderilir. */
var PUSU_NSS = (oda) => {
  oda.nsKirik = [];
  const L = oda.h?.kur?.nesneler || [];
  L.forEach((n, i) => {
    const e = { no: -(i + 1), tur: n.tur, can: n.can, tam: n.can, x: n.x, y: n.y, z: n.z, yaw: n.yaw || 0, hx: n.hx, hz: n.hz, boy: n.boy, ns: 1 };
    e.k = oda.d.dinamikEkle({ x: e.x, z: e.z, hx: e.hx, hz: e.hz, yaw: e.yaw, y0: e.y, y1: e.y + e.boy, mat: n.tur === "cam" ? "cam" : "tahta" });
    e.k.duvar = e;
    oda.duvarlar.push(e);
  });
  if (L.length) oda.botYol?.();
};

